referenceSolutions.javascript:
export function insertInterval(intervals            , added          )             {
  const result             = []; let [start,end] = added, i = 0; while (i < intervals.length && intervals[i][1] < start) result.push([...intervals[i++]]); while (i < intervals.length && intervals[i][0] <= end) { start = Math.min(start,intervals[i][0]); end = Math.max(end,intervals[i][1]); i++; } result.push([start,end]); while (i < intervals.length) result.push([...intervals[i++]]); return result;
}

